\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{tikz}
\usetikzlibrary{patterns,decorations.pathmorphing}

\title{Lecture Notes: The Damped Oscillator}
\author{Phys 221 Course Team}
\date{Spring 2026}

\begin{document}
\maketitle

\section{Setup}
Consider a block of mass $m$ attached to a light spring on a
frictionless rail. We write $x$ for the displacement of the
block from its equilibrium position. The restoring force is
$-kx$, where $k$ is the spring constant, and the dashpot adds
a viscous force proportional to the velocity. Newton's second
law then gives
\begin{equation}
m \frac{d^2 x}{dt^2} = -kx - c \frac{dx}{dt},
\label{eq:motion}
\end{equation}
where $c$ is the damping coefficient.

\section{Schematic}
Figure~\ref{fig:schematic} shows the arrangement. The named
coordinates used by the drawing code are internal to the
figure and are not mathematical symbols.

\begin{figure}[h]
\centering
\begin{tikzpicture}[scale=1.1]
\coordinate (wall) at (0,0);
\coordinate (x) at (3.5,0);
\fill[pattern=north east lines] (-0.2,-0.6) rectangle (0,0.6);
\draw[thick] (wall) -- (0.6,0);
\draw[decorate,decoration={coil,segment length=4pt}] (0.6,0) -- (2.7,0);
\draw[fill=gray!30] (2.7,-0.35) rectangle (x);
\draw[->,thick] (x) ++(0,0.55) -- ++(0.9,0) node[midway,above] {$v$};
\node[below=8pt] at (x) {block};
\draw[<->] (wall) ++(0,-0.9) -- ++(3.5,0) node[midway,below] {rest length};
\end{tikzpicture}
\caption{Spring--dashpot schematic.}
\label{fig:schematic}
\end{figure}

\section{Energy decay}
Multiplying \eqref{eq:motion} through by $dx/dt$ and
integrating over one cycle shows that the total energy
\begin{equation*}
E = \frac{1}{2} m \dot{x}^2 + \frac{1}{2} k x^2
\end{equation*}
decreases monotonically whenever $c > 0$. For light damping
the amplitude envelope decays as $x_{\max}(t) = x_0 e^{-ct/2m}$.

\section{Summary}
The sign of the damping term controls whether $x$ relaxes to
zero or grows without bound; a passive mechanical system
always has $c \ge 0$.
\end{document}

